import logging
from taf.ul.mobile.ui.android.utils import get_etree_html_object
from taf.ul.mobile.ui.android.mobile import Mobile
from taf.ul.mobile.ui.android.exceptions import SelectFailure


class Qualcomm(Mobile):

    _SEARCH_APN_RADIO_XPATH_TEMPLATE = ('//node[@text="{}"]/'
                                        '../..'
                                        '/node[@resource-id="com.android.settings:id/apn_radiobutton"]')

    def __init__(self, adb_proxy, **kwargs):
        super(Qualcomm, self).__init__(adb_proxy, **kwargs)

    def switch_network_mode(self, mode_name, restart_time):
        if self._get_configured_network_mode_name() == mode_name:
            logging.info("has selected specified mode, no action")
            self._close_setting()
            return

        self._select_5g_network_mode(mode_name)

        if self._get_configured_network_mode_name() != mode_name:
            raise SelectFailure(mode_name)

        self._close_setting()

    def _get_configured_network_mode_name(self):
        self._open_menu_by_searching_in_settings("Prefer 5G NR Mode")
        self._tap_prefer_5g_nr_mode()
        self._tap_sim_operator()
        return self._get_selected_node_title_in_dialog()

    def _get_search_menu_bounds(self):
        return self._get_menu_bounds("Search settings")

    def _tap_prefer_5g_nr_mode(self):
        self._click_menu("Prefer 5G NR Mode")

    def _tap_sim_operator(self):
        sim_operator_alpha = self._adb_proxy.get_sim_operator_alpha()
        self._click_menu(sim_operator_alpha)

    def _select_5g_network_mode(self, mode_name):
        self._click_menu(mode_name)

    def switch_apn(self, apn_name):
        if self.is_apn_selected(apn_name):
            logging.info("has selected specified apn, no action")
            return

        self._select_apn(apn_name)

        if not self.is_apn_selected(apn_name):
            raise SelectFailure("{} select failure, please check if apn is existed".format(apn_name))

    def is_apn_selected(self, apn_name):
        self._switch_to_access_point_names_page()
        return self._is_apn_selected(apn_name)

    def _switch_to_access_point_names_page(self):
        self._open_menu_by_searching_in_settings("Access Point Names")
        self._tap_access_point_names()

    def _tap_access_point_names(self):
        self._click_menu("Access Point Names")

    def _select_apn(self, apn_name):
        self._click_radio_button_by_title(apn_name)

    def _is_apn_selected(self, apn_name):
        xml_content = self._adb_proxy.get_ui_xml_content()
        xml_obj = get_etree_html_object(xml_content)
        searched_radio = xml_obj.xpath(self._SEARCH_APN_RADIO_XPATH_TEMPLATE.format(apn_name))
        if not searched_radio:
            raise SelectFailure("The apn {} not found or can not be selected".format(apn_name))

        searched_radio = searched_radio[0]
        return str(searched_radio.get("checked")) == "true"
